<?php
declare(strict_types=1);
session_name('ICTUSESSID');
session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS']),'samesite'=>'Lax','path'=>'/']);
session_start();
$dbHost=getenv('DB_HOST')?:'db'; $dbName=getenv('DB_NAME')?:'student_management'; $dbUser=getenv('DB_USER')?:'student_app'; $dbPass=getenv('DB_PASSWORD')?:'';
try {$pdo=new PDO("mysql:host=$dbHost;dbname=$dbName;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);}
catch(Throwable $e){http_response_code(503);error_log('Database connection failed: '.$e->getMessage());exit('<h1>Hệ thống tạm thời không khả dụng</h1><p>Vui lòng kiểm tra dịch vụ cơ sở dữ liệu.</p>');}
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function go(string $p='dashboard'):never{header('Location: /?page='.rawurlencode($p));exit;}
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
function csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(403);exit('Yêu cầu không hợp lệ. Vui lòng tải lại trang.');}}
// Tạo tài khoản demo lần đầu từ biến môi trường. Đổi mật khẩu trong .env trước khi chạy.
$adminEmail=getenv('DEMO_ADMIN_EMAIL')?:'admin@ICTU.local'; $adminPassword=getenv('DEMO_ADMIN_PASSWORD')?:'ChangeMe@12345';
$pdo->exec("CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(120) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$adminEmail]);if(!$q->fetch()){$q=$pdo->prepare('INSERT INTO users(email,password_hash,full_name,role) VALUES(?,?,?,?)');$q->execute([$adminEmail,password_hash($adminPassword,PASSWORD_DEFAULT),'Quản trị viên','admin']);}
$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();$action=$_POST['action']??'';
 if($action==='login'){$email=trim($_POST['email']??'');$password=(string)($_POST['password']??'');$q=$pdo->prepare('SELECT * FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch();if($u&&password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'email'=>$u['email'],'name'=>$u['full_name'],'role'=>$u['role']];$_SESSION['csrf']=bin2hex(random_bytes(32));$_SESSION['flash']='Đăng nhập thành công. Chào mừng bạn đến với ICTU.';go('dashboard');}$_SESSION['flash']='Email hoặc mật khẩu chưa chính xác.';header('Location: /?login=1');exit;}
 if($action==='logout'){$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain']??'',$p['secure'],$p['httponly']);}session_destroy();header('Location: /?login=1');exit;}
 if(empty($_SESSION['user'])){header('Location: /?login=1');exit;}
 $page=$_GET['page']??'students';
 try{
 if($action==='student_save'){$code=trim($_POST['student_code']??'');$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$class=(int)($_POST['class_id']??0);if(!$code||!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||$class<1)throw new RuntimeException('Vui lòng nhập đủ thông tin và email hợp lệ.');if(!empty($_POST['original_code'])){$q=$pdo->prepare('UPDATE students SET full_name=?,email=?,phone=?,date_of_birth=?,class_id=? WHERE student_code=?');$q->execute([$name,$email,trim($_POST['phone']??''),($_POST['date_of_birth']??'')?:null,$class,$_POST['original_code']]);}else{$q=$pdo->prepare('INSERT INTO students(student_code,full_name,email,phone,date_of_birth,class_id) VALUES(?,?,?,?,?,?)');$q->execute([$code,$name,$email,trim($_POST['phone']??''),($_POST['date_of_birth']??'')?:null,$class]);}$_SESSION['flash']='Đã lưu hồ sơ sinh viên.';go('students');}
 if($action==='student_delete'){$q=$pdo->prepare('DELETE FROM students WHERE student_code=?');$q->execute([$_POST['student_code']??'']);$_SESSION['flash']='Đã xóa sinh viên.';go('students');}
 if($action==='class_save'){$id=(int)($_POST['class_id']??0);$name=trim($_POST['class_name']??'');$major=trim($_POST['major']??'');if(!$name||!$major)throw new RuntimeException('Tên lớp và ngành học không được để trống.');if($id){$q=$pdo->prepare('UPDATE classes SET class_name=?,major=? WHERE id=?');$q->execute([$name,$major,$id]);}else{$q=$pdo->prepare('INSERT INTO classes(class_name,major) VALUES(?,?)');$q->execute([$name,$major]);}$_SESSION['flash']='Đã lưu lớp học.';go('classes');}
 if($action==='class_delete'){$q=$pdo->prepare('DELETE FROM classes WHERE id=?');$q->execute([(int)$_POST['class_id']]);$_SESSION['flash']='Đã xóa lớp học.';go('classes');}
 if($action==='grade_save'){$student=$_POST['student_code']??'';$subject=trim($_POST['subject_name']??'');$score=filter_var($_POST['score']??null,FILTER_VALIDATE_FLOAT);if(!$student||!$subject||$score===false||$score<0||$score>10)throw new RuntimeException('Điểm phải nằm trong khoảng từ 0 đến 10.');$id=(int)($_POST['grade_id']??0);if($id){$q=$pdo->prepare('UPDATE grades SET student_code=?,subject_name=?,score=?,semester=? WHERE id=?');$q->execute([$student,$subject,$score,trim($_POST['semester']??''),$id]);}else{$q=$pdo->prepare('INSERT INTO grades(student_code,subject_name,score,semester) VALUES(?,?,?,?)');$q->execute([$student,$subject,$score,trim($_POST['semester']??'')]);}$_SESSION['flash']='Đã lưu điểm số.';go('grades');}
 if($action==='grade_delete'){$q=$pdo->prepare('DELETE FROM grades WHERE id=?');$q->execute([(int)$_POST['grade_id']]);$_SESSION['flash']='Đã xóa điểm.';go('grades');}
 }catch(PDOException $ex){error_log('Database operation failed: '.$ex->getMessage());$_SESSION['flash']='Không thể lưu dữ liệu: dữ liệu có thể bị trùng hoặc vi phạm ràng buộc.';go($page);}catch(RuntimeException $ex){$_SESSION['flash']=$ex->getMessage();go($page);}
}
if(empty($_SESSION['user'])){ $login=true; }else{$login=isset($_GET['login']);}
if($login){?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đăng nhập • ICTU</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;font:15px system-ui,"Segoe UI",sans-serif;background:linear-gradient(135deg,#101b49,#344bc1 58%,#6c8cff);display:grid;place-items:center;padding:20px;color:#182230}.login{width:min(440px,100%);background:#fff;border-radius:22px;padding:36px;box-shadow:0 28px 80px #09113e55}.logo{display:flex;align-items:center;gap:12px;font-size:23px;font-weight:800;margin-bottom:30px}.mark{display:grid;place-items:center;background:#4263eb;color:white;border-radius:12px;width:46px;height:46px}.login h1{font-size:27px;margin:0 0 8px}.muted{color:#697586}.field{display:grid;gap:7px;margin:18px 0}.field label{font-weight:650;font-size:13px}input{width:100%;padding:13px;border:1px solid #d6ddea;border-radius:10px;font:inherit}input:focus{outline:2px solid #c8d2ff;border-color:#4263eb}.submit{width:100%;border:0;border-radius:10px;background:#4263eb;color:#fff;font:inherit;font-weight:700;padding:13px;cursor:pointer;margin-top:8px}.flash{padding:11px;background:#fff0f0;color:#a12828;border-radius:9px;margin:16px 0}.note{background:#f4f6ff;padding:12px;border-radius:10px;font-size:12px;line-height:1.6;margin-top:20px}.footer{text-align:center;margin-top:20px;font-size:12px;color:#697586}</style></head><body><section class="login"><div class="logo"><span class="mark">U</span> ICTU</div><h1>Đăng nhập hệ thống</h1><p class="muted">Vui lòng đăng nhập để quản lý sinh viên, lớp học và điểm số.</p><?php if($flash):?><div class="flash"><?=e($flash)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="login"><div class="field"><label for="email">Email tài khoản</label><input id="email" type="email" name="email" autocomplete="username" required autofocus placeholder="admin@ICTU.local"></div><div class="field"><label for="password">Mật khẩu</label><input id="password" type="password" name="password" autocomplete="current-password" required placeholder="Nhập mật khẩu"></div><button class="submit" type="submit">Đăng nhập</button></form><div class="note"><b>Tài khoản demo ban đầu</b><br>Email: <code><?=e($adminEmail)?></code><br>Mật khẩu: lấy từ <code>DEMO_ADMIN_PASSWORD</code> trong tệp <code>.env</code>. Hãy đổi mật khẩu trước khi sử dụng.</div><div class="footer">© ICTU • Hệ thống quản lý sinh viên</div></section></body></html><?php exit;}
$page=$_GET['page']??'dashboard';if(!in_array($page,['dashboard','students','classes','grades'],true))$page='dashboard';
$classes=$pdo->query('SELECT c.*,COUNT(s.student_code) student_count FROM classes c LEFT JOIN students s ON s.class_id=c.id GROUP BY c.id ORDER BY c.class_name')->fetchAll();$students=$pdo->query('SELECT s.*,c.class_name,c.major FROM students s JOIN classes c ON c.id=s.class_id ORDER BY s.full_name')->fetchAll();$grades=$pdo->query('SELECT g.*,s.full_name FROM grades g JOIN students s ON s.student_code=g.student_code ORDER BY g.id DESC')->fetchAll();
$studentCount=(int)$pdo->query('SELECT COUNT(*) FROM students')->fetchColumn();$classCount=(int)$pdo->query('SELECT COUNT(*) FROM classes')->fetchColumn();$gradeCount=(int)$pdo->query('SELECT COUNT(*) FROM grades')->fetchColumn();$avg=$pdo->query('SELECT AVG(score) FROM grades')->fetchColumn();
$editS=null;$editC=null;$editG=null;if(isset($_GET['edit_student'])){$q=$pdo->prepare('SELECT * FROM students WHERE student_code=?');$q->execute([$_GET['edit_student']]);$editS=$q->fetch()?:null;}if(isset($_GET['edit_class'])){$q=$pdo->prepare('SELECT * FROM classes WHERE id=?');$q->execute([(int)$_GET['edit_class']]);$editC=$q->fetch()?:null;}if(isset($_GET['edit_grade'])){$q=$pdo->prepare('SELECT * FROM grades WHERE id=?');$q->execute([(int)$_GET['edit_grade']]);$editG=$q->fetch()?:null;}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ICTU • Quản lý sinh viên</title><style>:root{--navy:#172554;--blue:#4263eb;--bg:#f4f7fb;--line:#e5eaf1;--muted:#697586}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#182230;font:14px system-ui,"Segoe UI",sans-serif}.layout{display:grid;grid-template-columns:225px 1fr;min-height:100vh}.side{background:var(--navy);color:#e8edff;padding:24px 15px}.brand{font-size:20px;font-weight:800;padding:0 10px 28px}.brand span{background:#8da2ff;color:#172554;border-radius:9px;padding:7px;margin-right:8px}.side a{display:block;color:#dbe4ff;text-decoration:none;padding:12px;border-radius:8px;margin:5px 0}.side a:hover,.side a.active{background:#2b3d78;color:white}.side .logout{margin-top:30px;border:1px solid #526394}.side form{margin:0}main{padding:28px;min-width:0}.top{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:22px}.top h1{margin:5px 0;font-size:27px}.muted{color:var(--muted)}.user{font-size:12px;background:white;border:1px solid var(--line);padding:10px 12px;border-radius:10px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:20px}.card,.panel{background:white;border:1px solid var(--line);border-radius:13px;box-shadow:0 6px 24px #1c2d5008}.card{padding:18px}.card strong{display:block;font-size:27px;margin:10px 0}.panel{overflow:hidden;margin-bottom:18px}.panelhead{padding:18px;display:flex;justify-content:space-between;gap:10px;align-items:center}.panelhead h2{margin:0 0 4px}.btn{display:inline-block;border:1px solid var(--line);background:white;padding:9px 12px;border-radius:8px;cursor:pointer;text-decoration:none;color:#182230;font:inherit}.primary{background:var(--blue);border-color:var(--blue);color:white}.danger{color:#b42318}.formgrid{padding:18px;display:flex;gap:10px;flex-wrap:wrap;align-items:end}.field{display:grid;gap:5px;min-width:160px;flex:1}.field label{font-weight:650;font-size:12px;color:#475467}input,select{border:1px solid #d5dce7;border-radius:8px;padding:10px;background:white;font:inherit;min-width:0;width:100%}.flash{background:#e5f7ef;color:#13724e;padding:12px 16px;border-radius:8px;margin-bottom:16px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:13px 15px;border-top:1px solid var(--line)}th{background:#f8fafc;color:#788395;font-size:11px;text-transform:uppercase}td{font-size:13px}.actions{display:flex;gap:6px}.inline{display:inline}.small{font-size:12px}.search{max-width:280px}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:175px 1fr}main{padding:16px}}@media(max-width:650px){.layout{display:block}.side{padding:12px;display:flex;flex-wrap:wrap;gap:4px}.brand{width:100%;padding:8px}.side a{padding:8px}.side form{margin-left:auto}.cards{gap:8px}.card{padding:12px}main{padding:12px}.top{align-items:flex-start;flex-direction:column}}</style></head><body><div class="layout"><aside class="side"><div class="brand"><span>U</span>ICTU</div><a class="<?= $page==='dashboard'?'active':'' ?>" href="/?page=dashboard">▦ Tổng quan</a><a class="<?= $page==='students'?'active':'' ?>" href="/?page=students">♙ Sinh viên</a><a class="<?= $page==='classes'?'active':'' ?>" href="/?page=classes">▤ Lớp học</a><a class="<?= $page==='grades'?'active':'' ?>" href="/?page=grades">▥ Điểm số</a><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="logout"><button class="btn logout" style="width:100%;background:transparent;color:white" type="submit">↪ Đăng xuất</button></form></aside><main><header class="top"><div><div class="muted small">UNI MANAGE / <?=e(strtoupper($page))?></div><h1>Hệ thống quản lý sinh viên</h1><div class="muted">Quản lý hồ sơ, lớp học và kết quả học tập.</div></div><div class="user">Đang đăng nhập: <b><?=e($_SESSION['user']['name'])?></b></div></header><?php if($flash):?><div class="flash"><?=e($flash)?></div><?php endif;?>
<?php if($page==='dashboard'):?><section class="cards"><div class="card"><span class="muted">Tổng sinh viên</span><strong><?=$studentCount?></strong><small>Hồ sơ trong MySQL</small></div><div class="card"><span class="muted">Số lớp học</span><strong><?=$classCount?></strong><small>Danh mục lớp</small></div><div class="card"><span class="muted">Bản ghi điểm</span><strong><?=$gradeCount?></strong><small>Kết quả học tập</small></div><div class="card"><span class="muted">Điểm trung bình</span><strong><?=number_format((float)$avg,2)?></strong><small>Thang điểm 10</small></div></section><section class="panel"><div class="panelhead"><div><h2>Truy cập hệ thống</h2><div class="muted">Các công cụ phục vụ triển khai và quản trị.</div></div></div><div class="formgrid"><a class="btn" href="/?page=students">Quản lý sinh viên</a><a class="btn" href="/?page=classes">Quản lý lớp học</a><a class="btn" href="/?page=grades">Quản lý điểm số</a><span class="muted">Grafana: localhost:3000 · Prometheus: localhost:9090</span></div></section>
<?php elseif($page==='students'):?><section class="panel"><div class="panelhead"><div><h2><?=$editS?'Cập nhật sinh viên':'Thêm sinh viên'?></h2><div class="muted">Thông tin được lưu trong cơ sở dữ liệu MySQL.</div></div></div><form method="post" class="formgrid"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="student_save"><input type="hidden" name="original_code" value="<?=e($editS['student_code']??'')?>"><div class="field"><label>Mã sinh viên *</label><input name="student_code" required value="<?=e($editS['student_code']??'')?>" maxlength="20" <?=$editS?'readonly':''?>></div><div class="field"><label>Họ và tên *</label><input name="full_name" required value="<?=e($editS['full_name']??'')?>"></div><div class="field"><label>Email *</label><input name="email" type="email" required value="<?=e($editS['email']??'')?>"></div><div class="field"><label>Điện thoại</label><input name="phone" value="<?=e($editS['phone']??'')?>"></div><div class="field"><label>Ngày sinh</label><input name="date_of_birth" type="date" value="<?=e($editS['date_of_birth']??'')?>"></div><div class="field"><label>Lớp *</label><select name="class_id" required><option value="">Chọn lớp</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=((int)($editS['class_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['class_name'])?></option><?php endforeach;?></select></div><button class="btn primary">Lưu sinh viên</button><?php if($editS):?><a class="btn" href="/?page=students">Hủy</a><?php endif;?></form></section><section class="panel"><div class="panelhead"><div><h2>Danh sách sinh viên</h2><div class="muted"><?=count($students)?> hồ sơ</div></div><input id="search" class="search" placeholder="Tìm mã, tên, email, lớp..."></div><div class="tablewrap"><table id="studentTable"><thead><tr><th>Mã SV</th><th>Họ tên</th><th>Email</th><th>Điện thoại</th><th>Lớp</th><th>Ngành</th><th>Thao tác</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><?=e($s['student_code'])?></td><td><?=e($s['full_name'])?></td><td><?=e($s['email'])?></td><td><?=e($s['phone'])?></td><td><?=e($s['class_name'])?></td><td><?=e($s['major'])?></td><td class="actions"><a class="btn" href="/?page=students&edit_student=<?=rawurlencode($s['student_code'])?>">Sửa</a><form class="inline" method="post" onsubmit="return confirm('Xóa sinh viên này?')"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="student_delete"><input type="hidden" name="student_code" value="<?=e($s['student_code'])?>"><button class="btn danger">Xóa</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
